from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found


class CustomerInsightsController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle_order_history(self, customer_id: str) -> Response:
        try:
            summaries = self._service.get_order_history(customer_id)
        except CustomerNotFound:
            return not_found("customer")

        orders_data: list[dict[str, Any]] = []
        for summary in summaries:
            orders_data.append({
                "order_id": summary.order.order_id,
                "status": summary.order.status,
                "total_cents": summary.total_cents,
            })

        return Response(200, {"customer_id": customer_id, "orders": orders_data})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        try:
            order_count, lifetime_value_cents = self._service.get_lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")

        return Response(200, {
            "customer_id": customer_id,
            "order_count": order_count,
            "lifetime_value_cents": lifetime_value_cents,
        })

    def handle_top_customers(self, limit: Any) -> Response:
        if type(limit) is not int or isinstance(limit, bool) or limit < 1:
            raise InvalidRequest("limit must be a positive integer")
        try:
            customers = self._service.get_top_customers(limit)
        except InvalidRequest as exc:
            return bad_request(exc)
        return Response(200, {"customers": customers})

    def handle_customers_without_orders(self) -> Response:
        customers = self._service.get_customers_without_orders()
        return Response(200, {"customers": customers})

def get_top_customers(self, limit: int) -> list[dict[str, str | int]]:
    """Return top customers by lifetime value (highest first, then by customer_id)."""
    customers_data = []
    for customer in self._customers.list_all():
        _, lifetime_value = self.get_lifetime_value(customer.customer_id)
        if lifetime_value > 0:
            customers_data.append({
                "customer_id": customer.customer_id,
                "name": customer.name,
                "lifetime_value_cents": lifetime_value,
            })
    customers_data.sort(key=lambda x: (-x["lifetime_value_cents"], x["customer_id"]))
    return customers_data[:limit]

